local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool
local UINavigationBarRoot = CS.UINavigationBarRoot
local UIModule = CS.Engine.UI.UIModule
local CSGameUtils = CS.GameUtils
local cs_coroutine = require 'XLua.cs_coroutine'
local CSPoolManager = CS.Engine.Lib.PoolManager.Instance
local dailyQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
